import { PRIVILEGES, type Privileges } from '../graph/access.js';
import type { Scope } from '../model/kinds.js';
import type { WebRole } from '../model/schema.js';

export const GENERATED_NOTE =
  '<!-- Generated by pageslens from the site configuration. Do not edit by hand; run `pageslens docs` again. -->';

const PRIVILEGE_LETTERS: Record<keyof Privileges, string> = {
  read: 'R',
  write: 'W',
  create: 'C',
  delete: 'D',
  append: 'A',
  appendto: 'T',
};

export const PRIVILEGE_LEGEND = 'R read · W write · C create · D delete · A append · T append to';

/** `RWC` for read, write and create. Empty string for none. */
export function privilegeLetters(privileges: Privileges): string {
  return PRIVILEGES.filter((p) => privileges[p])
    .map((p) => PRIVILEGE_LETTERS[p])
    .join('');
}

export function scopeLabel(scope: Scope): string {
  return scope.charAt(0).toUpperCase() + scope.slice(1);
}

/** Role name, marked when it's one of the built-in roles every visitor or signed-in user has. */
export function roleLabel(role: WebRole): string {
  if (role.anonymous) return `${role.name} (every visitor)`;
  if (role.authenticated) return `${role.name} (every signed-in user)`;
  return role.name;
}

export function code(text: string): string {
  return `\`${text.replaceAll('`', '')}\``;
}

/** A Markdown table; cells are escaped so `|` and line breaks don't break the row. */
export function table(header: string[], rows: string[][]): string {
  const line = (cells: string[]) => `| ${cells.map(escapeCell).join(' | ')} |`;
  return [line(header), line(header.map(() => '---')), ...rows.map(line)].join('\n');
}

function escapeCell(text: string): string {
  return text.replaceAll('|', '\\|').replace(/\r?\n/g, ' ');
}

/** GitHub heading anchor: lower case, spaces to dashes, punctuation dropped. */
export function anchor(heading: string): string {
  return heading
    .toLowerCase()
    .replace(/[^\p{L}\p{N}\s_-]/gu, '')
    .replace(/\s/g, '-');
}
